export const BASE='https://www.modeshift.app/api/v1/9814b106-2afe-47c8-919b-bdec6a5e521e/transport/';
export const distance=(a,b)=>{let r=Math.PI/180,x=(b.lat-a.lat)*r,y=(b.lon-a.lon)*r;return 6371000*2*Math.asin(Math.sqrt(Math.sin(x/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(y/2)**2))};
function csv(s){let rows=[],row=[],v='',q=false;for(let i=0;i<s.length;i++){let c=s[i];if(c==='"'){if(q&&s[i+1]==='"'){v+='"';i++}else q=!q}else if(c===','&&!q){row.push(v);v=''}else if(c==='\n'&&!q){row.push(v.replace(/\r$/,''));rows.push(row);row=[];v=''}else v+=c}if(v||row.length){row.push(v.replace(/\r$/,''));rows.push(row)}let h=rows.shift();return rows.filter(r=>r.length===h.length).map(r=>Object.fromEntries(h.map((k,i)=>[k.replace(/^\uFEFF/,''),r[i]])))}
async function unzip(ab){let v=new DataView(ab),b=new Uint8Array(ab),out={};let e=b.length-22;while(e>=0&&v.getUint32(e,true)!==0x06054b50)e--;if(e<0)throw Error('Invalid ZIP');let p=v.getUint32(e+16,true),n=v.getUint16(e+10,true);for(let i=0;i<n;i++){let method=v.getUint16(p+10,true),size=v.getUint32(p+20,true),nl=v.getUint16(p+28,true),el=v.getUint16(p+30,true),cl=v.getUint16(p+32,true),local=v.getUint32(p+42,true),name=new TextDecoder().decode(b.slice(p+46,p+46+nl));let start=local+30+v.getUint16(local+26,true)+v.getUint16(local+28,true),data=b.slice(start,start+size);if(name.endsWith('.txt')){if(method===8)data=new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer());else if(method!==0)throw Error('Unsupported ZIP');out[name]=csv(new TextDecoder().decode(data))}p+=46+nl+el+cl}return out}
export async function load(){let url=BASE+'gtfs/gtfs.zip',r;try{r=await fetch(url,{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('Schedule HTTP '+r.status);if(typeof caches!=='undefined'){let c=await caches.open('tuka-schedule');await c.put(url,r.clone())}}catch(e){if(typeof caches!=='undefined')r=await caches.match(url);if(!r)throw e}let f=await unzip(await r.arrayBuffer());let db={stops:f['stops.txt'].map(s=>({...s,id:s.stop_id,name:s.stop_name,lat:+s.stop_lat,lon:+s.stop_lon})),routes:new Map(f['routes.txt'].map(r=>[r.route_id,r])),trips:new Map(f['trips.txt'].map(t=>[t.trip_id,t])),times:new Map(),byStop:new Map(),calendar:f['calendar.txt'],exceptions:f['calendar_dates.txt'],info:f['feed_info.txt'][0],shapes:new Map()};for(let s of f['stop_times.txt']){let t={...s,seq:+s.stop_sequence,seconds:seconds(s.departure_time)};if(!db.times.has(s.trip_id))db.times.set(s.trip_id,[]);db.times.get(s.trip_id).push(t);if(!db.byStop.has(s.stop_id))db.byStop.set(s.stop_id,[]);db.byStop.get(s.stop_id).push(t)}for(let t of db.times.values())t.sort((a,b)=>a.seq-b.seq);for(let p of f['shapes.txt']||[]){if(!db.shapes.has(p.shape_id))db.shapes.set(p.shape_id,[]);db.shapes.get(p.shape_id).push([+p.shape_pt_lon,+p.shape_pt_lat,+p.shape_pt_sequence])}for(let p of db.shapes.values())p.sort((a,b)=>a[2]-b[2]);return db}
function fields(b){let p=0,out={};function varint(){let v=0n,shift=0n;while(p<b.length){let c=b[p++];v|=BigInt(c&127)<<shift;if(!(c&128))return Number(BigInt.asIntN(64,v));shift+=7n}throw Error('Invalid protobuf')}while(p<b.length){let tag=varint(),k=tag>>3,w=tag&7,val;if(w===0)val=varint();else if(w===2){let n=varint();val=b.slice(p,p+n);p+=n}else if(w===1){p+=8;continue}else if(w===5){val=new DataView(b.buffer,b.byteOffset+p,4).getFloat32(0,true);p+=4}else throw Error('Unsupported protobuf');(out[k]??=[]).push(val)}return out}
const str=b=>b?new TextDecoder().decode(b):'';const first=(f,k)=>f[k]?.[0];
export async function realtime(){let r=await fetch(BASE+'gtfsrt/tripupdates.pb',{cache:'no-store',signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('Realtime HTTP '+r.status);let f=fields(new Uint8Array(await r.arrayBuffer())),head=fields(first(f,1)),timestamp=first(head,3),updates=new Map(),vehicles=[];for(let raw of f[2]||[]){let entity=fields(raw);if(first(entity,4)){let v=fields(first(entity,4)),td=first(v,1)?fields(first(v,1)):{},p=first(v,2)?fields(first(v,2)):{},descriptor=first(v,8)?fields(first(v,8)):{};if(first(p,1)!=null&&first(p,2)!=null)vehicles.push({id:str(first(descriptor,1))||str(first(entity,1)),label:str(first(descriptor,2)),tripId:str(first(td,1)),routeId:str(first(td,5)),date:str(first(td,3)),lat:first(p,1),lon:first(p,2),bearing:first(p,3),timestamp:first(v,5)||timestamp,seq:first(v,3),stopId:str(first(v,7))})}if(!first(entity,3))continue;let u=fields(first(entity,3)),trip=fields(first(u,1)),id=str(first(trip,1)),start=str(first(trip,3)),rel=first(trip,4);for(let rawstop of u[2]||[]){let s=fields(rawstop),event=first(s,2)||first(s,3),ev=event?fields(event):{},delay=first(ev,1);if(delay>2147483647)delay-=4294967296;updates.set(id+'|'+str(first(s,4))+'|'+start,{time:first(ev,2),delay,relationship:first(s,5),tripRelationship:rel,seq:first(s,1)})}}return {timestamp,updates,vehicles}}
export function seconds(s){return s.split(':').reduce((a,n)=>a*60+ +n,0)}
export function serviceDay(offset=0){let parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Skopje',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),o=Object.fromEntries(parts.map(p=>[p.type,p.value]));let d=new Date(Date.UTC(+o.year,+o.month-1,+o.day+offset));let date=d.toISOString().slice(0,10).replaceAll('-','');let noon=Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate(),12);let localHour=+new Intl.DateTimeFormat('en',{timeZone:'Europe/Skopje',hour:'numeric',hourCycle:'h23'}).format(new Date(noon));return {date,weekday:['sunday','monday','tuesday','wednesday','thursday','friday','saturday'][d.getUTCDay()],midnight:noon-(localHour*3600000)}}
export function active(db,day){let ids=new Set(db.calendar.filter(c=>c.start_date<=day.date&&c.end_date>=day.date&&c[day.weekday]==='1').map(c=>c.service_id));for(let e of db.exceptions.filter(e=>e.date===day.date)){if(e.exception_type==='1')ids.add(e.service_id);else ids.delete(e.service_id)}return ids}
export function departures(db,rt,id,now=Date.now(),limit=16){let list=[];let fresh=rt&&Math.abs(now/1000-rt.timestamp)<120;for(let offset of [-1,0,1]){let day=serviceDay(offset),ids=active(db,day);for(let s of db.byStop.get(id)||[]){let trip=db.trips.get(s.trip_id);if(!ids.has(trip.service_id))continue;let predicted=fresh?(rt.updates.get(s.trip_id+'|'+id+'|'+day.date)||rt.updates.get(s.trip_id+'|'+id+'|')):null;if(predicted?.relationship===1||predicted?.tripRelationship===3)continue;let scheduled=day.midnight+s.seconds*1000;let time=predicted?.time?predicted.time*1000:scheduled+(predicted?.delay??0)*1000;if(time<now-20000||time>now+4*3600000)continue;list.push({trip,s,route:db.routes.get(trip.route_id),time,scheduled,live:!!predicted&&(predicted.time!=null||predicted.delay!=null),day})}}return list.sort((a,b)=>a.time-b.time).slice(0,limit)}
// Earliest-arrival rounds: walking access, up to three bus rides, walking egress.
export function planJourney(db,rt,origin,destination,now=Date.now()){
 const walkMs=meters=>Math.ceil(meters*1.3/75)*60000,stops=db.stops.filter(s=>db.byStop.has(s.id)),byId=new Map(stops.map(s=>[s.id,s])),fresh=rt&&Math.abs(now/1000-rt.timestamp)<120;
 const access=stops.map(s=>({s,dist:distance(origin,s)})).filter(x=>x.dist<=800),egress=new Map(stops.map(s=>[s.id,distance(s,destination)]).filter(x=>x[1]<=800));
 let labels=new Map(access.map(x=>[x.s.id,{time:now+walkMs(x.dist),legs:[{type:'walk',from:origin,to:x.s,start:now,end:now+walkMs(x.dist),meters:x.dist}]}])),results=[];
 let direct=distance(origin,destination);if(direct<=1800)results.push({arrival:now+walkMs(direct),legs:[{type:'walk',from:origin,to:destination,start:now,end:now+walkMs(direct),meters:direct}]});
 let runs=[];for(let offset of [-1,0,1]){let day=serviceDay(offset),services=active(db,day);for(let [id,trip]of db.trips){if(!services.has(trip.service_id))continue;let path=db.times.get(id);if(!path?.length)continue;let timed=[],cancelled=false,prev=0;for(let p of path){let u=fresh?(rt.updates.get(id+'|'+p.stop_id+'|'+day.date)||rt.updates.get(id+'|'+p.stop_id+'|')):null;if(u?.tripRelationship===3){cancelled=true;break}let scheduled=day.midnight+p.seconds*1000;let time=u?.time?u.time*1000:scheduled+(u?.delay??0)*1000;time=Math.max(prev,time);prev=time;timed.push({p,time,live:!!u&&(u.time!=null||u.delay!=null),skip:u?.relationship===1})}if(cancelled||timed.at(-1).time<now||timed[0].time>now+4*3600000)continue;runs.push({id,trip,timed})}}
 for(let round=0;round<3;round++){
  let reached=new Map();for(let run of runs){let boarded=null;for(let i=0;i<run.timed.length;i++){let x=run.timed[i];if(x.skip)continue;if(boarded&&x.time<=now+4*3600000){let prior=reached.get(x.p.stop_id);if(!prior||x.time<prior.time){let leg={type:'bus',route:db.routes.get(run.trip.route_id),headsign:run.trip.trip_headsign,tripId:run.id,from:byId.get(boarded.x.p.stop_id),to:byId.get(x.p.stop_id),start:boarded.x.time,end:x.time,live:boarded.x.live,arrivalLive:x.live,stops:i-boarded.index};reached.set(x.p.stop_id,{time:x.time,legs:[...boarded.label.legs,leg]})}}if(!boarded){let label=labels.get(x.p.stop_id);if(label&&label.time<=x.time&&x.time>=now){boarded={label,x,index:i}}}}}
  for(let [id,label]of reached){let meters=egress.get(id);if(meters!=null){let end=label.time+walkMs(meters);results.push({arrival:end,legs:[...label.legs,{type:'walk',from:byId.get(id),to:destination,start:label.time,end,meters}]})}}
  if(round===2)break;let next=new Map();db.walkTransfers??=new Map();for(let [id,label]of reached){let neighbors=db.walkTransfers.get(id);if(!neighbors){let at=byId.get(id);neighbors=stops.map(s=>({s,dist:distance(at,s)})).filter(x=>x.dist<=250);db.walkTransfers.set(id,neighbors)}for(let x of neighbors){let end=label.time+walkMs(x.dist)+120000,old=next.get(x.s.id);if(!old||end<old.time){next.set(x.s.id,{time:end,legs:[...label.legs,{type:'transfer',from:byId.get(id),to:x.s,meters:x.dist,start:label.time,end}]})}}}labels=next;
 }
 let seen=new Set();return results.sort((a,b)=>a.arrival-b.arrival).filter(r=>{let k=r.legs.filter(l=>l.type==='bus').map(l=>l.tripId).join('|')||'walk';if(seen.has(k))return false;seen.add(k);return true}).slice(0,5)
}
